<div class="ui segment container center aligned" id="social-posts-container"><h3 class="ui header">{{ sify('最新社群動態') }}</h3><div class="ui three stackable cards" v-if="posts.length &gt; 0"><div class="ui card" v-for="post in posts" :key="post.id"><div class="content"><div class="header"><a :href="`https://g0v.social/@${post.account?.username}`" target="_blank" rel="noopener noreferrer"><img class="ui avatar image" :src="post.account.avatar" :alt="post.account.display_name || post.account.username || '未知用戶'">{{ post.account.display_name || post.account.username || '未知用戶' }}</a></div><div class="meta"><span class="date">{{ formatDate(post.created_at) }}</span></div><div class="description"><p v-html="truncateContentAndEscape(post.content)"></p></div><div class="extra"><a class="ui basic button" :href="`https://g0v.social/@${post.account?.username}/${post.id}`" target="_blank" rel="noopener noreferrer"><i class="external alternate icon"></i>{{ sify('查看原文') }}</a></div></div><div class="extra content" v-if="post.media_attachments &amp;&amp; post.media_attachments.length &gt; 0"><img class="ui fluid image" :src="post.media_attachments[0].preview_url" :alt="post.media_attachments[0].description || '圖片'"></div></div></div><div class="ui message" v-else-if="!loading"><div class="content"><p>{{ sify('目前沒有相關的動態貼文') }}</p></div></div><div class="ui loader" v-if="loading"></div></div>