<div class="hello"><h3 class="ui header">{{sify('知識倒溯與前推')}}</h3><select class="ui dropdown" @change="onSelectUnit" v-model="selectedUnit"><option :value="null" selected>{{sify('選擇一個單元')}}</option><option v-for="unit in units" :value="unit.id" :key="unit.id">{{ unit.n }}</option></select><div class="ui divider"></div><div class="ui grid" v-if="currentUnit"><div class="ui stackable row"><div class="five wide padded left aligned column"><div class="padded"><h4 class="ui orange header">當前單元</h4><a @click="op(currentUnit.url, currentUnit.n, currentUnit.pro, currentUnit.wiki)" target="_blank" rel="noopener noreferrer"><img :src="'https://www.google.com/s2/favicons?domain='+currentUnit.url" :alt="sify(currentUnit.n)"><!--i.download.icon--><span class="orange" v-if="!useWiki">{{ sify(currentUnit.n) }}</span><span class="orange" v-else>{{sify(currentUnit.wiki)}}</span><!-- .ui.teal.label(v-show="currentUnit.pro") pro--><span class="gray" v-if="currentUnit.d">-{{ sify(currentUnit.d) }}</span></a></div></div><div class="five wide padded left aligned column"><div class="padded"><h4 class="ui purple header">{{sify('先備知識')}}</h4><div class="ui list"><div class="item" v-for="u in prerequisiteUnits" :key="u.id"><a @click="op(u.url, u.n, u.pro, u.wiki)" target="_blank" rel="noopener noreferrer"><img :src="'https://www.google.com/s2/favicons?domain='+u.url" :alt="sify(u.n)" v-if="!useWiki"><img src="https://www.google.com/s2/favicons?domain=https://zh.wikipedia.org" :alt="sify(u.n)" v-else><!--i.download.icon--><span v-if="!useWiki">{{ sify(u.n) }}</span><span v-else>{{sify(u.wiki)}}</span><!-- .ui.teal.label(v-show="u.pro") pro--><span class="gray" v-if="u.d">-{{ sify(u.d) }}</span><br><button class="ui basic purple button" @click="selectedUnit = u.id">{{ sify('往前倒溯') }}</button></a></div></div></div></div><div class="five wide padded left aligned column"><div class="padded"><h4 class="ui blue header">{{sify('後續知識')}}</h4><div class="ui list"><div class="item" v-for="u in postrequisiteUnits" :key="u.id"><a @click="op(u.url, u.n, u.pro, u.wiki)" target="_blank" rel="noopener noreferrer"><img :src="'https://www.google.com/s2/favicons?domain='+u.url" :alt="sify(u.n)" v-if="!useWiki"><img src="https://www.google.com/s2/favicons?domain=https://zh.wikipedia.org" :alt="sify(u.n)" v-else><!--i.download.icon--><span v-if="!useWiki">{{ sify(u.n) }}</span><span v-else>{{sify(u.wiki)}}</span><!-- .ui.teal.label(v-show="u.pro") pro--><span class="gray" v-if="u.d">-{{ sify(u.d) }}</span><br><button class="ui basic orange button" @click="selectedUnit = u.id">{{ sify('往後前推') }}</button></a></div></div></div></div></div></div><div class="ui divider"></div><d3-network v-show="selectedUnit !== null" ref="net" :net-nodes="filteredNodes" :net-links="filteredLinks" :options="options" style="width: 100%; height: 100%;"></d3-network></div>