<div class="hello"><div class="ui container"><!--.ui.segmentp(v-for = "q in quizs", :key = "q.q")
  | {{ q.q }} {{ q.as }} {{q.t}}--><h1 v-if="err">{{err}}</h1><div v-if="myQ.q"><img class="q" v-if="myQ.img" :src="myQ.img"><h1 class="ui header">{{myQ.q}}<div class="sub header">{{myQ.c}}(等級{{myQ.l}})</div></h1><div class="ui buttons"><a class="ui huge button" :class="myA == a ? 'green' : 'gray'" v-for="a in myQ.as" @click="myA = a; check(a, myQ.t)">{{a}}</a></div></div><h1 v-if="win"><a @click="resetO()">你答對了！按Enter鍵或點這裡繼續...<img class="good" src="../assets/th.jpg"></a></h1><h1 v-if="wrong">不對喔，請再加油！</h1><hr v-if="myQ.q"><div><div class="ui vertical buttons"><a class="ui red large basic button" v-if="myQ.q &amp;&amp; myLev &gt; 1" @click="levup(-1)">降級測驗</a><a class="ui green large button" v-if="myQ.q" @click="resetO()">同級測驗</a><a class="ui orange large basic button" v-if="myQ.q &amp;&amp; myLev &lt; maxLev" @click="levup(1)">升級測驗</a></div></div><hr v-if="myQ.q"><div class="ui grid container"><div class="ui stackable row"><div class="eight wide column" v-if="myQ.q"><h3>參考教材</h3><span v-for="u in units"><a :href="u.url" v-if="u.n === myC" target="_blank">{{u.n}}</a></span></div><div class="column" :class="myQ.q ? 'eight wide' : 'sixteen wide'"><h3>選擇單元</h3><div class="ui vertical buttons"><a class="ui large button" :class="myC == c ? 'green' : 'gray'" v-for="c in myCs" @click="setC(c)">{{c}}</a><a class="ui large blue button" @click="reset()">隨機</a></div></div></div></div></div></div>