<div class="hello"><br><h2>閃卡</h2><h3>（按任意鍵翻牌）</h3><div class="ui form container no-print"><div class="inline fields"><div class="field"><div class="ui labeled input"><div class="ui label">數字下限</div><input id="r" type="number" v-model="min" step="5"></div></div><div class="field"><div class="ui labeled input"><div class="ui label">數字上限</div><input id="r" type="number" v-model="range" step="5" autofocus=""></div></div></div><div class="inline fields"><label>選擇算法：</label><div class="field" v-for="o in ops"><div class="ui radio checkbox"><input type="radio" name="year" v-bind:value="o.v" v-model="op"><label class="clickable" @click="op = o.v">{{o.t}}</label></div></div></div></div><div class="ui centered red card clickable" v-if="!flip" @click="flipCard()"><h1 class="ui header" v-if="op == '+'">{{ n1 }} + {{ n2 }} = ?</h1><h1 class="ui header" v-if="op == '-'">{{ n1 }} - {{ n2 }} = ?</h1><h1 class="ui header" v-if="op == '*'">{{ n1 }} &times; {{ n2 }} = ?</h1></div><div class="ui centered orange fliped card clickable" v-else="" @click="flipCard()"><h1 class="ui blue header" v-if="op == '+'">{{ n1 + n2 }}</h1><h1 class="ui blue header" v-if="op == '-'">{{ n1 - n2 }}</h1><h1 class="ui blue header" v-if="op == '*'">{{ n1 * n2 }}</h1></div></div>