<div class="coins-container"><div class="ui container"><h2 class="page-title">{{ sify('兌幣練習') }}</h2><div class="split-zones"><div class="zone-wrapper"><div class="zone-label">{{ sify('左側') }}</div><div class="drop-zone" @dragover.prevent @drop="onDrop($event, 'left')" @dragenter.prevent @dragleave.prevent ref="dropZoneLeft"><div class="placed-coins"><template v-for="(coin, index) in leftCoins" :key="coin.id + '-L-' + index"><div class="placed-coin" :draggable="true" @dragstart="onPlacedCoinDragStart($event, index, 'left')" @touchstart="onTouchStart($event, coin, 'placed', index, 'left')" :class="{ 'is-rect': coin.shape === 'rect' }" :style="coinStyle(coin)"><span class="coin-value">${{ coin.value }}</span></div></template></div><div class="drop-zone-text" v-if="leftCoins.length === 0"><p>{{ sify('將硬幣拖曳到此處') }}</p></div></div><div class="zone-total">{{ sify('總額') }}：${{ leftTotal }}</div></div><div class="zone-divider">+</div><div class="zone-wrapper"><div class="zone-label">{{ sify('右側（自動兌幣）') }}</div><div class="drop-zone" @dragover.prevent @drop="onDrop($event, 'right')" @dragenter.prevent @dragleave.prevent ref="dropZoneRight"><div class="placed-coins"><template v-for="(coin, index) in rightCoins" :key="coin.id + '-R-' + index"><div class="placed-coin" :draggable="!coin.merging" @dragstart="onPlacedCoinDragStart($event, index, 'right')" @touchstart="onTouchStart($event, coin, 'placed', index, 'right')" :class="{ 'is-rect': coin.shape === 'rect', 'is-merging': coin.merging, 'is-appearing': coin.appearing }" :style="coinStyle(coin)"><span class="coin-value">${{ coin.value }}</span></div></template></div><div class="drop-zone-text" v-if="rightCoins.length === 0"><p>{{ sify('將硬幣拖曳到此處') }}</p></div></div><div class="zone-total">{{ sify('總額') }}：${{ rightTotal }}</div></div></div><div class="exchange-log" v-if="exchangeLog.length &gt; 0"><transition-group name="log-fade" tag="div"><div class="log-item" v-for="(entry, i) in exchangeLog" :key="entry.id"><span class="log-arrow">⇒</span>{{ entry.text }}</div></transition-group></div><div class="equation-box" v-if="showEquation"><span class="eq-text">${{ leftTotal }} + ${{ rightTotal }} = ${{ leftTotal + rightTotal }}</span></div><div class="ui buttons"><button class="ui button teal" @click="toggleEquation"><span v-if="!showEquation">{{ sify('合計') }}</span><span v-else>{{ sify('隱藏總合') }}</span></button><button class="ui button primary" @click="clearAll">{{ sify('清除全部') }}</button></div><div class="coins-toolbar" @dragover.prevent @drop="onToolbarDrop($event)"><div class="coin-item" v-for="coin in availableCoins" :key="coin.id" :draggable="true" @dragstart="onDragStart($event, coin)" @touchstart="onTouchStart($event, coin, 'toolbar')" :class="{ 'is-rect': coin.shape === 'rect' }" :style="toolbarCoinStyle(coin)"><span class="coin-value">${{ coin.value }}</span></div></div><div class="placed-coin" v-if="touchDragging &amp;&amp; touchDragCoin &amp;&amp; touchDragCoin.x !== null &amp;&amp; touchDragCoin.y !== null" :class="{ 'is-rect': touchDragCoin &amp;&amp; touchDragCoin.shape === 'rect' }" :style="touchFloatStyle"><span class="coin-value">${{ touchDragCoin && touchDragCoin.value }}</span></div></div></div>