<h3 class="ui header" id="changelogs">{{ sify('版本更新公告')}}<div v-for="(c, idx) in changelogs.slice(0, 3)" :key="idx"><router-link class="sub header" v-if="c.r" :to="c.r">{{c.text}}</router-link><a class="sub header" v-else-if="c.h" :href="c.h" target="_blank" rel="noopener noreferrer">{{c.text}}</a><span class="sub header" v-else>{{c.text}}</span></div></h3>